import { base } from 'viem/chains'
import { describe, expect, test } from 'vitest'
import { accountA, accountB, passkeyAccount } from '../../test/consts'
import { RhinestoneSDK } from '..'
import { resolveCallInputs } from '../execution/utils'
import { MULTI_FACTOR_VALIDATOR_ADDRESS } from '../modules/validators/core'
import { enable, removeSubValidator, setSubValidator } from './mfa'

const accountAddress = '0x36C03e7D593F7B2C6b06fC18B5f4E9a4A29C99b0'
const customValidatorModule = '0x1111111111111111111111111111111111111111'

const ensValidator = {
  type: 'ens' as const,
  accounts: [accountB, accountA],
  ownerExpirations: [100, 200],
  threshold: 2,
}

describe('Multi-Factor Actions', () => {
  describe('Set Sub-Validator', () => {
    test('ECDSA stateless calldata', () => {
      expect(
        setSubValidator(1, { type: 'ecdsa', accounts: [accountA] }),
      ).toEqual({
        to: MULTI_FACTOR_VALIDATOR_ADDRESS,
        value: 0n,
        data: '',
      })
    })

    test('passkey stateless calldata uses a custom factor module', () => {
      expect(
        setSubValidator(0x1234, {
          type: 'passkey',
          accounts: [passkeyAccount],
          module: customValidatorModule,
        }),
      ).toEqual({
        to: MULTI_FACTOR_VALIDATOR_ADDRESS,
        value: 0n,
        data: '',
      })
    })

    test('ENS stateless calldata', () => {
      expect(setSubValidator(2, ensValidator)).toEqual({
        to: MULTI_FACTOR_VALIDATOR_ADDRESS,
        value: 0n,
        data: '',
      })
    })
  })

  test('enables an ENS factor', async () => {
    const rhinestone = new RhinestoneSDK({ apiKey: 'test' })
    const rhinestoneAccount = await rhinestone.createAccount({
      owners: { type: 'ecdsa', accounts: [accountA] },
    })

    const calls = await resolveCallInputs(
      [enable([ensValidator])],
      rhinestoneAccount.config,
      base,
      accountAddress,
    )

    expect(calls).toEqual([
      {
        to: accountAddress,
        value: 0n,
        data: '',
      },
    ])
  })

  test('removes an ENS factor', () => {
    expect(removeSubValidator(2, ensValidator)).toEqual({
      to: MULTI_FACTOR_VALIDATOR_ADDRESS,
      value: 0n,
      data: '0x324857780000000000000000000000005049ecbd4d961ae6dfeed9b7ccce7f026454970e0000000000000000000000020000000000000000000000000000000000000000',
    })
  })
})
